CREATE FUNCTION pg_temp.assert_true(value boolean,label text) RETURNS void LANGUAGE plpgsql AS $$BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION '%',label;END IF;END$$;
CREATE FUNCTION pg_temp.as_user(n integer,action text,payload jsonb) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN PERFORM set_config('request.jwt.claims',jsonb_build_object('sub','00000000-0000-4000-8000-'||lpad(n::text,12,'0'),'session_id','10000000-0000-4000-8000-'||lpad(n::text,12,'0'))::text,true);RETURN public.cbgpu_school_clubs_api(action,payload);END$$;
DO $$DECLARE campaign uuid:=(SELECT(value->>'id')::uuid FROM fixture_clubs_state WHERE key='campaign');club uuid:=(SELECT(value->>'id')::uuid FROM fixture_clubs_state WHERE key='club');a cbgpu_schools.club_applications;p cbgpu_schools.club_campaigns;result jsonb;draft jsonb;BEGIN
PERFORM pg_temp.assert_true((SELECT count(*)=1 FROM cbgpu_schools.club_applications WHERE club_id=club AND status='APPROVED'),'atomic capacity under race');
SELECT * INTO a FROM cbgpu_schools.club_applications WHERE club_id=club AND status='APPROVED';
BEGIN PERFORM pg_temp.as_user(CASE WHEN right(a.applicant_id::text,1)='6' THEN 7 ELSE 6 END,'application_withdraw',jsonb_build_object('school_id','clubs-school-1','club_id',club,'application_id',a.id,'expected_revision',a.revision));RAISE EXCEPTION 'FOREIGN_WITHDRAWAL';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
PERFORM pg_temp.as_user(right(a.applicant_id::text,1)::integer,'application_withdraw',jsonb_build_object('school_id','clubs-school-1','club_id',club,'application_id',a.id,'expected_revision',a.revision));
SELECT * INTO a FROM cbgpu_schools.club_applications WHERE club_id=club AND status='PENDING';
PERFORM pg_temp.as_user(5,'application_review',jsonb_build_object('school_id','clubs-school-1','club_id',club,'application_id',a.id,'expected_revision',a.revision,'status','APPROVED'));
PERFORM pg_temp.assert_true((SELECT count(*)=2 FROM cbgpu_schools.club_applications WHERE club_id=club),'withdraw/review preserves application history');
SELECT * INTO p FROM cbgpu_schools.club_campaigns WHERE id=campaign;
result:=pg_temp.as_user(1,'campaign_update',jsonb_build_object('school_id','clubs-school-1','campaign_id',campaign,'expected_revision',p.revision,'status','PAUSED','confirmed',true));
PERFORM pg_temp.assert_true(result#>>'{campaign,status}'='PAUSED' AND NOT(result#>>'{campaign,application_open}')::boolean,'pause status-only CAS and authoritative windows');
BEGIN PERFORM pg_temp.as_user(4,'apply',jsonb_build_object('school_id','clubs-school-1','club_id',club,'answers','teacher'));RAISE EXCEPTION 'TEACHER_APPLICATION';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
BEGIN PERFORM pg_temp.as_user(5,'apply',jsonb_build_object('school_id','clubs-school-1','club_id',club,'answers','paused'));RAISE EXCEPTION 'PAUSED_APPLICATION';EXCEPTION WHEN serialization_failure THEN NULL;END;
UPDATE cbgpu_schools.club_campaigns SET status='ACTIVE',registration_ends_at=clock_timestamp()-interval '1 second' WHERE id=campaign;
result:=pg_temp.as_user(5,'list','{"school_id":"clubs-school-1"}');
PERFORM pg_temp.assert_true(NOT(result#>>'{items,0,can_edit}')::boolean,'ready editing stops at registration end');
BEGIN PERFORM pg_temp.as_user(5,'update',jsonb_build_object('school_id','clubs-school-1','club_id',club,'expected_revision',2,'title','Too late'));RAISE EXCEPTION 'LATE_READY_EDIT';EXCEPTION WHEN serialization_failure THEN NULL;END;
draft:=pg_temp.as_user(5,'create',jsonb_build_object('school_id','clubs-school-1','campaign_id',campaign,'title','Next draft','description','Preparation remains private'))->'club';
PERFORM pg_temp.assert_true((draft->>'can_edit')::boolean AND NOT(draft->>'can_submit_ready')::boolean,'draft prep anytime but ready window enforced');
BEGIN PERFORM pg_temp.as_user(5,'ready',jsonb_build_object('school_id','clubs-school-1','club_id',draft->>'id','expected_revision',draft->'revision'));RAISE EXCEPTION 'READY_OUTSIDE_WINDOW';EXCEPTION WHEN serialization_failure THEN NULL;END;
UPDATE cbgpu_schools.club_campaigns SET promotion_starts_at=clock_timestamp()+interval '1 hour',application_starts_at=clock_timestamp()+interval '1 hour' WHERE id=campaign;
result:=pg_temp.as_user(6,'list',jsonb_build_object('school_id','clubs-school-1','campaign_id',campaign));
PERFORM pg_temp.assert_true(result->>'total'='1' AND result#>>'{items,0,my_application,id}' IS NOT NULL AND NOT(result#>>'{items,0,can_apply}')::boolean,'own application survives before promotion without reopening application');
UPDATE cbgpu_schools.club_campaigns SET registration_starts_at=now()-interval '5 days',registration_ends_at=now()-interval '4 days',promotion_starts_at=now()-interval '4 days',promotion_ends_at=now()-interval '1 day',application_starts_at=now()-interval '3 days',application_ends_at=now()-interval '2 days' WHERE id=campaign;
result:=pg_temp.as_user(6,'list','{"school_id":"clubs-school-1"}');PERFORM pg_temp.assert_true(result->>'total'='1' AND NOT(result#>>'{items,0,published}')::boolean,'own application survives ended campaign without promotion');
result:=pg_temp.as_user(6,'list',jsonb_build_object('school_id','clubs-school-1','campaign_id',campaign));PERFORM pg_temp.assert_true(result->>'total'='1' AND NOT(result#>>'{items,0,can_apply}')::boolean,'internal historical ready entry preserved without live applications');
BEGIN PERFORM pg_temp.as_user(5,'apply',jsonb_build_object('school_id','clubs-school-1','club_id',club));RAISE EXCEPTION 'EXPIRED_APPLICATION_WINDOW';EXCEPTION WHEN serialization_failure THEN NULL;END;
result:=pg_temp.as_user(1,'list','{"school_id":"clubs-school-1","limit":1}');
PERFORM pg_temp.assert_true(result#>>'{campaigns,1,club_count}' IS NOT NULL OR result#>>'{campaigns,0,club_count}' IS NOT NULL,'admin receives actual aggregate counts');
result:=pg_temp.as_user(6,'list','{"school_id":"clubs-school-1"}');PERFORM pg_temp.assert_true(position('application_count' IN result::text)=0,'member never receives privileged aggregate fields');
UPDATE cbgpu_schools.feature_registry SET enabled=false WHERE key='clubs';
BEGIN PERFORM pg_temp.as_user(5,'list','{"school_id":"clubs-school-1"}');RAISE EXCEPTION 'DISABLED_CLUBS';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
UPDATE cbgpu_schools.feature_registry SET enabled=true WHERE key='clubs';
UPDATE cbgpu_schools.memberships SET verified=false WHERE user_id='00000000-0000-4000-8000-000000000005' AND school_id='clubs-school-1';
BEGIN PERFORM pg_temp.as_user(5,'applications',jsonb_build_object('school_id','clubs-school-1','club_id',club));RAISE EXCEPTION 'REVOKED_FOUNDER_PII';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
UPDATE cbgpu_schools.memberships SET verified=true WHERE user_id='00000000-0000-4000-8000-000000000005' AND school_id='clubs-school-1';
UPDATE cbgpu_schools.clubs SET status='WITHDRAWN' WHERE id=club;
result:=pg_temp.as_user(7,'list','{"school_id":"clubs-school-1"}');
PERFORM pg_temp.assert_true(result->>'total'='1' AND result#>>'{items,0,my_application,id}' IS NOT NULL AND NOT(result#>>'{items,0,published}')::boolean AND NOT(result#>>'{items,0,can_apply}')::boolean,'founder withdrawal preserves only own application record');
result:=pg_temp.as_user(4,'list','{"school_id":"clubs-school-1"}');PERFORM pg_temp.assert_true(result->>'total'='0','non-applicant cannot view withdrawn promotion');
SELECT * INTO a FROM cbgpu_schools.club_applications WHERE club_id=club AND applicant_id='00000000-0000-4000-8000-000000000007';
PERFORM pg_temp.as_user(7,'application_withdraw',jsonb_build_object('school_id','clubs-school-1','club_id',club,'application_id',a.id,'expected_revision',a.revision));
DELETE FROM public.profiles WHERE id='00000000-0000-4000-8000-000000000007';
result:=pg_temp.as_user(5,'applications',jsonb_build_object('school_id','clubs-school-1','club_id',club));
PERFORM pg_temp.assert_true(jsonb_array_length(result->'items')=(result->>'total')::integer AND result->>'total'='2','missing profile never drops application or stalls pagination');
DELETE FROM auth.sessions WHERE user_id='00000000-0000-4000-8000-000000000006';
BEGIN PERFORM pg_temp.as_user(6,'list','{"school_id":"clubs-school-1"}');RAISE EXCEPTION 'REVOKED_SESSION';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END$$;
SELECT pg_temp.assert_true(NOT has_table_privilege('authenticated','cbgpu_schools.club_applications','SELECT'),'no direct browser applicant table access');
SELECT pg_temp.assert_true(NOT has_table_privilege('authenticated','cbgpu_schools.clubs','INSERT'),'no direct browser club writes');
SELECT pg_temp.assert_true(NOT has_function_privilege('anon','public.cbgpu_school_clubs_api(text,jsonb)','EXECUTE'),'no anonymous school club access');
SELECT 'CLUB_WINDOWS_PRIVACY_CAPACITY_RACE_TESTS_PASSED';
